/** Original fictional procedure semantics; exact source identities are retained across NL stages. */
export type SourceRecord = { id: string; path: string; text: string; sha256: string };
export type Witness = { sourceId: string; path: string; quote: string };
export type LocalDecision = { id: string; site: string; inputIds: string[]; contribution: string; witnesses: Witness[] };
export type StateValue = string | number | boolean | null;
export type StateAtom = { key: string; subject: string; value: StateValue; known: boolean; establishedAt: number | null; witnesses: Witness[] };
export type ScenarioEvent = { id: string; time: number; actor: string; meaning: string; witnesses: Witness[] };
export type ScenarioInput = { id: string; initial: StateAtom[]; events: ScenarioEvent[]; requiredObservables: string[]; witnesses: Witness[] };
export type ProcedureSnapshot = { revision: string; records: SourceRecord[]; scenarios: ScenarioInput[] };
export type CompilerRequest = { id: string; outputPackage: string; entryName: string; requiredScenarios: string[]; objective: string };
export type CompilationGoal = { requiredBehavior: string[]; preservedUncertainty: string[]; outputResponsibilities: string[]; witnesses: Witness[]; unresolved: string[] };
export type Intake = { snapshot: ProcedureSnapshot; request: CompilerRequest; goal: CompilationGoal; editions: SourceRecord[]; rules: SourceRecord[]; exceptions: SourceRecord[]; scenarios: ScenarioInput[]; context: SourceRecord[]; unresolved: string[] };
export type SourceClause = { id: string; editionId: string; issuer: string; meaning: string; effectiveFrom: number | null; effectiveUntil: number | null; witnesses: Witness[] };
export type AuthorityDecision = { editionId: string; adopted: boolean | null; competent: boolean | null; scope: string[]; reason: string; witnesses: Witness[]; localDecision: LocalDecision };
export type EditionSelection = { selectedClauses: SourceClause[]; replacedClauseIds: string[]; preservedClauseIds: string[]; authorityDecisions: AuthorityDecision[]; unresolved: string[] };
export type ExceptionBinding = { exceptionClauseId: string; waivedPrerequisiteIds: string[]; retainedDutyIds: string[]; scopeMeaning: string; unresolved: string[]; localDecision: LocalDecision };
export type RuleMeaning = { id: string; clauseIds: string[]; actorRole: string; action: string; prerequisiteMeanings: { id: string; meaning: string; stateKeys: string[] }[]; effectMeaning: string; scopeMeaning: string; exceptionBindings: ExceptionBinding[]; witnesses: Witness[]; unresolved: string[] };
export type RequirementSet = { selection: EditionSelection; rules: RuleMeaning[]; permissions: RuleMeaning[]; forbiddenConsequences: string[]; unresolved: string[] };
export type StateField = { key: string; valueType: 'string' | 'number' | 'boolean'; ownerRole: string; unknownAllowed: boolean; premiseClauseIds: string[]; meaning: string; witnesses: Witness[] };
export type StateSchema = { fields: StateField[]; identityRules: string[]; invariants: string[]; unresolved: string[] };
export type DependencyEdge = { beforeRuleId: string; afterRuleId: string; kind: 'requires' | 'invalidates' | 'alternative'; meaning: string; witnesses: Witness[] };
export type DependencyComponent = { id: string; ruleIds: string[]; internalEdges: DependencyEdge[]; status: 'ordered' | 'unresolved-cycle'; orderedRuleIds: string[]; reason: string; witnesses: Witness[] };
export type ComponentFrontier = { remaining: DependencyComponent[]; settled: DependencyComponent[]; requirements: RequirementSet; unresolved: string[] };
export type DependencyGraph = { edges: DependencyEdge[]; components: DependencyComponent[]; unresolved: string[] };
export type ProcedureModel = { requirements: RequirementSet; schema: StateSchema; dependencies: DependencyGraph; unresolved: string[] };
export type CallBoundary = { ruleIds: string[]; kind: 'named' | 'scoped-literal'; typedInputs: { name: string; type: string }[]; typedOutput: string; captures: string[]; consumerFields: string[]; reason: string; localDecision: LocalDecision };
export type BranchPlan = { ruleId: string; guardMeaning: string; trueEffect: string; falseEffect: string; unknownEffect: string; requiredStateKeys: string[]; witnesses: Witness[] };
export type ModulePlan = { path: string; responsibility: string; ruleIds: string[]; inputs: { name: string; type: string }[]; outputType: string; ownedFields: string[]; calls: string[]; boundaries: CallBoundary[]; branches: BranchPlan[]; witnesses: Witness[] };
export type GeneratedSpan = { path: string; quote: string };
export type ContributionAudit = { path: string; substantive: boolean | null; consumedChildFields: string[]; consumedLiteralFields: string[]; findings: string[]; witnesses: Witness[]; generatedEvidence: GeneratedSpan[]; localDecision: LocalDecision };
export type GeneratedModule = { path: string; text: string; plan: ModulePlan; contributionAudit: ContributionAudit };
export type GeneratedProgram = { entryPath: string; modules: GeneratedModule[]; typeFiles: { path: string; text: string }[]; sourceToModule: { clauseId: string; paths: string[] }[]; unresolved: string[] };
export type GuardDecision = { ruleId: string; eventId: string; value: boolean | null; sourceRequiredValue: boolean | null; matchesSource: boolean | null; sourceRequiredEffects: StateAtom[]; generatedEvidence: GeneratedSpan[]; sourceLocalDecision: LocalDecision; satisfiedPremiseIds: string[]; missingPremiseIds: string[]; waivedPremiseIds: string[]; effects: StateAtom[]; reason: string; witnesses: Witness[]; localDecision: LocalDecision };
export type ScenarioTrace = { scenarioId: string; eventId: string; stateBefore: StateAtom[]; sourceStateBefore: StateAtom[]; decisions: GuardDecision[]; stateAfter: StateAtom[]; sourceStateAfter: StateAtom[]; observable: string; witnesses: Witness[] };
export type ScenarioFrontier = { scenario: ScenarioInput; remainingEventIds: string[]; atoms: StateAtom[]; sourceAtoms: StateAtom[]; traces: ScenarioTrace[]; program: GeneratedProgram; model: ProcedureModel; unresolved: string[] };
export type ScenarioVerdict = { scenarioId: string; valid: boolean | null; traces: ScenarioTrace[]; satisfiedObservables: string[]; violatedObservables: string[]; unresolved: string[]; witnesses: Witness[] };
export type ScenarioSuiteResult = { verdicts: ScenarioVerdict[]; unresolved: string[] };
export type RevisionTarget = { id: string; scenarioId: string; earliestEventId: string | null; affectedRuleIds: string[]; affectedPaths: string[]; violatedMeaning: string; repairObligation: string; witnesses: Witness[]; unresolved: string[] };
export type RevisionState = { program: GeneratedProgram; suite: ScenarioSuiteResult; remainingScenarioIds: string[]; targets: RevisionTarget[]; settledScenarioIds: string[]; findings: string[]; model: ProcedureModel; intake: Intake };
export type InterfaceFinding = { caller: string; callee: string; field: string; preserved: boolean | null; reason: string; witnesses: Witness[]; generatedEvidence: GeneratedSpan[] };
export type CompilationAudit = { interfaces: InterfaceFinding[]; sourceComplete: boolean | null; scenarioComplete: boolean | null; contributionComplete: boolean | null; findings: string[]; unresolved: string[] };
export type CompilePacket = { requestId: string; program: GeneratedProgram; model: ProcedureModel; suite: ScenarioSuiteResult; audit: CompilationAudit; revisions: RevisionTarget[]; unresolved: string[] };

export type OperationReading = { operation: string; actual: boolean | null; witnesses: Witness[] };
export type AttemptReading = { permission: boolean | null; missing: string[]; waived: string[]; witnesses: Witness[] };
